class SellerInventory:
    def __init__(self):
        self.seller_inventory_map = {}

    def add_items_to_inventory(self, product_id, count):
        self.seller_inventory_map[product_id] = (
            self.seller_inventory_map.get(product_id, 0) + count
        )

    def delete_items(self, product_id, count):
        if count > self.seller_inventory_map.get(product_id, 0):
            raise ValueError("Not enough items")
        self.seller_inventory_map[product_id] -= count

